"""M2.2b: shapes and lower thirds as the export button now sends them. The frontend mapper's own output (export_layers.json, synthetic data, generated by the frontend test)
is valid for the real request schema, and the real renderer draws it where the editor has it: positions, colours, border, full-width banner, circle, lower-third bar. No database."""
import json
import subprocess
from pathlib import Path

import pytest
from PIL import Image

from app.schemas.video_export import ExportLowerThird, ExportProjectRequest, ExportShape
from app.services import ffmpeg_svc

FIXTURE = Path(__file__).resolve().parents[2] / "frontend" / "src" / "pages" / "video-studio-v2" / "export" / "__fixtures__" / "export_layers.json"
USER_ID = 999
W, H = 320, 180


@pytest.fixture(scope="module")
def parts() -> dict:
    assert FIXTURE.exists(), "run the frontend export tests once (UPDATE_LAYER_EXPORT_FIXTURE=1) to generate the fixture"
    return json.loads(FIXTURE.read_text(encoding="utf-8"))


def test_the_mappers_output_is_valid_for_the_existing_request_schema(parts):
    clip = {"asset_id": 1, "start_time": 0, "end_time": 3, "trim_in": 0}
    req = ExportProjectRequest(canvas_width=W, canvas_height=H, video_clips=[clip], **parts)         # raises if any field is unknown to, or wrongly typed for, the schema
    assert len(req.shapes) == 3 and len(req.lower_thirds) == 2
    assert all(isinstance(s, ExportShape) for s in req.shapes) and all(isinstance(l, ExportLowerThird) for l in req.lower_thirds)
    assert [s.kind for s in req.shapes] == ["rectangle", "circle", "banner"] and req.shapes[2].full_width is True
    assert all(0 <= s.opacity <= 1 and s.end_time > s.start_time for s in req.shapes)


def _near(c, ref, tol=45):
    return all(abs(a - b) <= tol for a, b in zip(c, ref))


@pytest.mark.asyncio
async def test_the_real_renderer_draws_them_where_the_editor_has_them(parts, clips, tmp_path):
    project = {
        "canvas_width": W, "canvas_height": H,
        "video_clips": [{"path": clips[1], "trim_in": 0, "start_time": 0, "end_time": 3, "speed": 1, "color_grade": "none", "brightness": 0, "contrast": 0, "saturation": 0,
                         "transition": "cut", "transition_duration": 0.5, "has_separated_audio": False}],
        "text_overlays": [], "audio_tracks": [], "shapes": parts["shapes"], "lower_thirds": parts["lower_thirds"],
    }
    out = await ffmpeg_svc.render_project(project, USER_ID)
    frame = tmp_path / "f.png"
    subprocess.run([ffmpeg_svc.FFMPEG_BIN, "-y", "-v", "error", "-ss", "2.0", "-i", str(out), "-frames:v", "1", str(frame)], check=True, capture_output=True)
    im = Image.open(frame).convert("RGB")
    base = im.getpixel((300, 5))                                                                    # the plain video, untouched by any layer
    assert _near(im.getpixel((round(W * 0.70), round(H * 0.56))), (0, 170, 255)), "the circle (60%+10%, 50%+6%) is drawn, opaque, in its own colour"
    assert _near(im.getpixel((34, 50)), (255, 255, 255)), "the rectangle's 4 px white border sits inside its box at (10%, 20%)"
    assert _near(im.getpixel((80, 50)), (255, 136, 0), 60), "the rectangle's fill is drawn inside the border"
    for x in (2, W - 3):
        px = im.getpixel((x, 168))
        assert not _near(px, base, 20) and px[1] < base[1], "the full-width banner (y 90-96%) reaches both canvas edges and darkens the video at 60 % opacity"
    assert _near(im.getpixel((27, 118)), (31, 143, 143), 50), "the second lower third (8%, 60%) draws its teal accent bar at its left edge"
    assert not _near(im.getpixel((100, 128)), base, 25), "...and its translucent dark chip over the video"
